-- ============================================================
-- SEED DATA: 557 CANCIONES PARA KARAOKE JL MUSIC
-- ============================================================

ON CONFLICT (numero) DO UPDATE SET titulo = EXCLUDED.titulo, artista = EXCLUDED.artista, genero = EXCLUDED.genero, video_url = EXCLUDED.video_url;

-- Ajustar secuencia
SELECT setval('canciones_id_seq', coalesce((SELECT max(id) + 1 FROM canciones), 1), false);